CREATE TABLE public.ketosis_stages (id uuid DEFAULT gen_random_uuid() NOT NULL, mode text NOT NULL, stage_name text NOT NULL, min_mmol numeric, max_mmol numeric, color text, status_label text, sort_order smallint NOT NULL);
ALTER TABLE public.ketosis_stages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ketosis_stages ADD CONSTRAINT ketosis_stages_mode_check CHECK (mode = ANY (ARRAY['diabetic'::text, 'non_diabetic'::text]));
ALTER TABLE public.ketosis_stages ADD CONSTRAINT ketosis_stages_mode_sort_order_key UNIQUE (mode, sort_order);
ALTER TABLE public.ketosis_stages ADD CONSTRAINT ketosis_stages_mode_stage_name_key UNIQUE (mode, stage_name);
ALTER TABLE public.ketosis_stages ADD CONSTRAINT ketosis_stages_pkey PRIMARY KEY (id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.ketosis_stages TO anon;
GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.ketosis_stages TO authenticated;
GRANT ALL ON public.ketosis_stages TO service_role;
CREATE POLICY "Ketosis stages are viewable by all authenticated users" ON public.ketosis_stages FOR SELECT TO authenticated USING (true);
CREATE TABLE public.readings (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, meter_id uuid, type text NOT NULL, value numeric NOT NULL, unit text NOT NULL, ketosis_stage_id uuid, measured_at timestamp with time zone DEFAULT now() NOT NULL, source text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.readings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.readings ADD CONSTRAINT readings_ketosis_stage_id_fkey FOREIGN KEY (ketosis_stage_id) REFERENCES public.ketosis_stages(id) ON DELETE SET NULL;
ALTER TABLE public.readings ADD CONSTRAINT readings_meter_id_fkey FOREIGN KEY (meter_id) REFERENCES public.devices(id) ON DELETE SET NULL;
ALTER TABLE public.readings ADD CONSTRAINT readings_pkey PRIMARY KEY (id);
ALTER TABLE public.readings ADD CONSTRAINT readings_source_check CHECK (source = ANY (ARRAY['device'::text, 'manual'::text]));
ALTER TABLE public.readings ADD CONSTRAINT readings_type_check CHECK (type = ANY (ARRAY['ketone'::text, 'glucose'::text]));
ALTER TABLE public.readings ADD CONSTRAINT readings_unit_check CHECK (unit = ANY (ARRAY['mmol/L'::text, 'mg/dL'::text]));
ALTER TABLE public.readings ADD CONSTRAINT readings_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.readings TO anon;
GRANT ALL ON public.readings TO authenticated;
GRANT ALL ON public.readings TO service_role;
CREATE INDEX readings_user_measured_at_idx ON public.readings (user_id, measured_at DESC);
CREATE POLICY "Readings are deletable by owner" ON public.readings FOR DELETE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Readings are insertable by owner" ON public.readings FOR INSERT TO authenticated WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Readings are updatable by owner" ON public.readings FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Readings are viewable by owner" ON public.readings FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
